import asyncioimport loggingimport osimport shutilfrom datetime import datetime, timedeltafrom collections import defaultdictimport aiosqlitefrom aiogram import Bot, Dispatcher, F, Routerfrom aiogram.types import (    Message, CallbackQuery, InlineKeyboardMarkup, InlineKeyboardButton,    ReplyKeyboardMarkup, KeyboardButton, ChatJoinRequest, FSInputFile)from aiogram.filters import Commandfrom aiogram.fsm.context import FSMContextfrom aiogram.fsm.state import State, StatesGroupfrom aiogram.fsm.storage.memory import MemoryStoragefrom aiogram.client.default import DefaultBotPropertiesfrom aiogram.enums import ParseMode, ChatMemberStatusBOT_TOKEN = os.getenv("8884566648:AAHfgBeRni5dCYhCGKxvFyyKMu6RUg-8WCs")OWNER_ID  = 8175768073DB_FILE = "/app/data/vipbot.db"TOKEN_START_BONUS    = 10TOKEN_REFER_BONUS    = 4TOKEN_GET_VIDEO      = 2TOKEN_BACCA          = 10TOKEN_VIRAL_VIP      = 10VIDEO_DELETE_MIN     = 15VIP_VIDEO_DELETE_MIN = 30BCL_DELETE_HOURS     = 24FORCE_JOIN_CHECK_SEC = 600logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(name)s - %(levelname)s - %(message)s")log = logging.getLogger("VIPBot")bot = Bot(token=BOT_TOKEN, default=DefaultBotProperties(parse_mode=ParseMode.HTML))dp  = Dispatcher(storage=MemoryStorage())router = Router()dp.include_router(router)DB: aiosqlite.Connection = Noneuser_locks = defaultdict(asyncio.Lock)# ==================== DB INIT ====================async def db_init():    global DB    # ✅ ফোল্ডার তৈরি করা (Railway Volume এর জন্য)    os.makedirs("/app/data", exist_ok=True)        DB = await aiosqlite.connect(DB_FILE)    DB.row_factory = aiosqlite.Row    await DB.execute("PRAGMA journal_mode=WAL")    await DB.execute("PRAGMA synchronous=NORMAL")    await DB.execute("PRAGMA busy_timeout=8000")    await DB.execute("PRAGMA cache_size=-64000")    await DB.execute("PRAGMA temp_store=MEMORY")    await DB.execute("CREATE TABLE IF NOT EXISTS users (user_id INTEGER PRIMARY KEY, name TEXT, username TEXT, tokens INTEGER DEFAULT 0, refer_by INTEGER, refer_count INTEGER DEFAULT 0, videos_seen INTEGER DEFAULT 0, is_banned INTEGER DEFAULT 0, joined_at TEXT)")    await DB.execute("CREATE TABLE IF NOT EXISTS videos (id INTEGER PRIMARY KEY AUTOINCREMENT, file_id TEXT, vtype TEXT, caption TEXT, added_at TEXT)")    await DB.execute("CREATE TABLE IF NOT EXISTS vip_videos (id INTEGER PRIMARY KEY AUTOINCREMENT, plan TEXT, file_id TEXT, vtype TEXT, caption TEXT, added_at TEXT)")    await DB.execute("CREATE TABLE IF NOT EXISTS channels (chat_id TEXT PRIMARY KEY, title TEXT, invite_link TEXT, added_at TEXT)")    await DB.execute("CREATE TABLE IF NOT EXISTS redeem (code TEXT PRIMARY KEY, tokens INTEGER, used_by INTEGER, created TEXT)")    await DB.execute("CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT)")    await DB.execute("CREATE TABLE IF NOT EXISTS delete_queue (id INTEGER PRIMARY KEY AUTOINCREMENT, chat_id INTEGER, message_id INTEGER, delete_at TEXT, done INTEGER DEFAULT 0)")    await DB.execute("CREATE TABLE IF NOT EXISTS broadcast (id INTEGER PRIMARY KEY AUTOINCREMENT, media_type TEXT, file_id TEXT, caption TEXT, price INTEGER, locked_type TEXT, locked_file_id TEXT, locked_caption TEXT, sent INTEGER DEFAULT 0, failed INTEGER DEFAULT 0, created TEXT)")    await DB.execute("CREATE TABLE IF NOT EXISTS broadcast_links (id INTEGER PRIMARY KEY AUTOINCREMENT, media_type TEXT, file_id TEXT, caption TEXT, price INTEGER, locked_type TEXT, locked_file_id TEXT, locked_caption TEXT, sent INTEGER DEFAULT 0, failed INTEGER DEFAULT 0, created TEXT)")    await DB.execute("CREATE TABLE IF NOT EXISTS pending_joins (user_id INTEGER, chat_id TEXT, PRIMARY KEY(user_id, chat_id))")    # ✅ Link-Video ব্যাচের টেবিল    await DB.execute("CREATE TABLE IF NOT EXISTS link_videos (id INTEGER PRIMARY KEY AUTOINCREMENT, batch_id TEXT, file_id TEXT, vtype TEXT, caption TEXT, added_at TEXT)")    await DB.execute("CREATE TABLE IF NOT EXISTS link_batches (batch_id TEXT PRIMARY KEY, owner_id INTEGER, created TEXT)")    await DB.execute("CREATE INDEX IF NOT EXISTS idx_users_banned ON users(is_banned)")    await DB.execute("CREATE INDEX IF NOT EXISTS idx_users_tokens ON users(tokens)")    await DB.execute("CREATE INDEX IF NOT EXISTS idx_del_queue ON delete_queue(done, delete_at)")    await DB.execute("CREATE INDEX IF NOT EXISTS idx_link_batch ON link_videos(batch_id)")    await DB.commit()    log.info("✅ SQLite ready (High Load Mode)")async def db_close():    if DB: await DB.close()    async def is_bot_on() -> bool:    async with DB.execute("SELECT value FROM settings WHERE key='bot_status'") as cur:        row = await cur.fetchone()    return True if not row else row["value"] == "1"async def set_bot_status(on: bool):    await DB.execute("INSERT INTO settings(key,value) VALUES('bot_status',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", ("1" if on else "0",))    await DB.commit()async def get_user(uid: int) -> dict:    async with DB.execute("SELECT * FROM users WHERE user_id=?", (uid,)) as cur:        row = await cur.fetchone()    if row: return dict(row)    await DB.execute("INSERT INTO users(user_id,tokens,joined_at) VALUES(?,?,?)", (uid, TOKEN_START_BONUS, datetime.utcnow().isoformat()))    await DB.commit()    async with DB.execute("SELECT * FROM users WHERE user_id=?", (uid,)) as cur:        row = await cur.fetchone()    return dict(row)async def update_user_name(uid: int, name: str, username: str):    await DB.execute("UPDATE users SET name=?, username=? WHERE user_id=?", (name or "", username or "", uid))    await DB.commit()async def add_token(uid: int, amount: int):    await DB.execute("UPDATE users SET tokens=tokens+? WHERE user_id=?", (amount, uid))    await DB.commit()async def deduct_token(uid: int, amount: int) -> bool:    async with user_locks[uid]:        async with DB.execute("SELECT tokens FROM users WHERE user_id=?", (uid,)) as cur:            row = await cur.fetchone()        if not row or row["tokens"] < amount: return False        await DB.execute("UPDATE users SET tokens=tokens-? WHERE user_id=?", (amount, uid))        await DB.commit()        return Trueasync def get_all_channels() -> list:    async with DB.execute("SELECT * FROM channels") as cur:        rows = await cur.fetchall()    return [dict(r) for r in rows]async def schedule_delete(chat_id: int, message_id: int, delete_at: datetime):    await DB.execute("INSERT INTO delete_queue(chat_id,message_id,delete_at,done) VALUES(?,?,?,0)", (chat_id, message_id, delete_at.isoformat()))    await DB.commit()async def is_user_joined_all(uid: int) -> bool:    async with DB.execute("SELECT chat_id FROM channels") as cur:        channels = await cur.fetchall()    if not channels: return True    async def check_single_channel(chat_id_str):        chat_id = int(chat_id_str)        try:            member = await bot.get_chat_member(chat_id=chat_id, user_id=uid)            if member.status in (ChatMemberStatus.MEMBER, ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.CREATOR, ChatMemberStatus.RESTRICTED):                return True        except Exception:            pass        async with DB.execute("SELECT 1 FROM pending_joins WHERE user_id=? AND chat_id=?", (uid, str(chat_id))) as cur:            if await cur.fetchone(): return True        return False    results = await asyncio.gather(*(check_single_channel(ch["chat_id"]) for ch in channels))    return all(results)async def get_not_joined_channels(uid: int) -> list:    async with DB.execute("SELECT * FROM channels") as cur:        channels = await cur.fetchall()    if not channels: return []    async def check_single_channel(ch):        chat_id = int(ch["chat_id"])        try:            member = await bot.get_chat_member(chat_id=chat_id, user_id=uid)            if member.status in (ChatMemberStatus.MEMBER, ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.CREATOR, ChatMemberStatus.RESTRICTED):                return None        except Exception:            pass        async with DB.execute("SELECT 1 FROM pending_joins WHERE user_id=? AND chat_id=?", (uid, str(chat_id))) as cur:            if await cur.fetchone(): return None        return dict(ch)    results = await asyncio.gather(*(check_single_channel(ch) for ch in channels))    return [ch for ch in results if ch is not None]async def force_join_keyboard_for(uid: int) -> InlineKeyboardMarkup:    not_joined = await get_not_joined_channels(uid)    kb = [[InlineKeyboardButton(text=f"📢 𝐉𝐎𝐈𝐍 {ch.get('title','𝐂𝐇𝐀𝐍𝐍𝐄𝐋')}", url=ch["invite_link"])] for ch in not_joined]    kb.append([InlineKeyboardButton(text="✅ 𝐂𝐇𝐄𝐂𝐊 𝐉𝐎𝐈𝐍", callback_data="check_join")])    return InlineKeyboardMarkup(inline_keyboard=kb)async def force_join_keyboard() -> InlineKeyboardMarkup:    channels = await get_all_channels()    kb = [[InlineKeyboardButton(text=f"📢 𝐉𝐎𝐈𝐍 {ch.get('title','𝐂𝐇𝐀𝐍𝐍𝐄𝐋')}", url=ch["invite_link"])] for ch in channels]    kb.append([InlineKeyboardButton(text="✅ 𝐂𝐇𝐄𝐂𝐊 𝐉𝐎𝐈𝐍", callback_data="check_join")])    return InlineKeyboardMarkup(inline_keyboard=kb)async def require_join(event) -> bool:    if isinstance(event, CallbackQuery):        uid, sender = event.from_user.id, event.message    else:        uid, sender = event.from_user.id, event    if await is_user_joined_all(uid): return True    if isinstance(event, CallbackQuery):        try: await event.answer("❌ 𝐉𝐎𝐈𝐍 𝐀𝐋𝐋 𝐂𝐇𝐀𝐍𝐍𝐄𝐋𝐒 𝐅𝐈𝐑𝐒𝐓!", show_alert=True)        except Exception: pass    await sender.answer(        "🔒 <b>𝐅𝐎𝐑𝐂𝐄 𝐉𝐎𝐈𝐍</b>\n\n𝐏𝐥𝐞𝐚𝐬𝐞 𝐣𝐨𝐢𝐧 𝐭𝐡𝐞 𝐜𝐡𝐚𝐧𝐧𝐞𝐥𝐬 𝐛𝐞𝐥𝐨𝐰 𝐚𝐧𝐝 𝐭𝐚𝐩 𝐂𝐡𝐞𝐜𝐤 𝐉𝐨𝐢𝐧.",        reply_markup=await force_join_keyboard_for(uid)    )    return False# ==================== WORKERS ====================async def delete_worker():    while True:        try:            now = datetime.utcnow().isoformat()            async with DB.execute("SELECT id,chat_id,message_id FROM delete_queue WHERE done=0 AND delete_at<=?", (now,)) as cur:                rows = await cur.fetchall()            for r in rows:                try: await bot.delete_message(r["chat_id"], r["message_id"])                except Exception: pass                await DB.execute("UPDATE delete_queue SET done=1 WHERE id=?", (r["id"],))            if rows: await DB.commit()        except Exception as e:            log.error(f"delete_worker error: {e}")        await asyncio.sleep(30)async def force_join_worker():    while True:        await asyncio.sleep(FORCE_JOIN_CHECK_SEC)        try:            channels = await get_all_channels()            if not channels: continue            async with DB.execute("SELECT user_id FROM users WHERE is_banned=0") as cur:                users = await cur.fetchall()            for i in range(0, len(users), 50):                chunk = users[i:i+50]                for u in chunk:                    uid = u["user_id"]                    if not await is_user_joined_all(uid):                        try:                            await bot.send_message(                                uid,                                "🔒 <b>𝐅𝐎𝐑𝐂𝐄 𝐉𝐎𝐈𝐍 𝐑𝐄𝐌𝐈𝐍𝐃𝐄𝐑</b>\n\n𝐏𝐥𝐞𝐚𝐬𝐞 𝐣𝐨𝐢𝐧 𝐭𝐡𝐞 𝐜𝐡𝐚𝐧𝐧𝐞𝐥𝐬 𝐛𝐞𝐥𝐨𝐰 𝐚𝐧𝐝 𝐭𝐚𝐩 𝐂𝐡𝐞𝐜𝐤 𝐉𝐨𝐢𝐧.",                                reply_markup=await force_join_keyboard_for(uid)                            )                        except Exception: pass                        await asyncio.sleep(0.05)                await asyncio.sleep(1)        except Exception as e:            log.error(f"force_join_worker: {e}")            # ==================== KEYBOARDS & STATES ====================def home_keyboard() -> ReplyKeyboardMarkup:    return ReplyKeyboardMarkup(        keyboard=[            [KeyboardButton(text="📸 𝐆𝐄𝐓 𝐕𝐈𝐃𝐄𝐎"), KeyboardButton(text="👑 𝐕𝐈𝐏 𝐕𝐈𝐃𝐄𝐎")],            [KeyboardButton(text="🔗 𝐑𝐄𝐅𝐄𝐑"), KeyboardButton(text="🎁 𝐑𝐄𝐃𝐄𝐄𝐌")],            [KeyboardButton(text="💰 𝐁𝐀𝐋𝐀𝐍𝐂𝐄"), KeyboardButton(text="🛒 𝐁𝐔𝐘 𝐓𝐎𝐊𝐄𝐍")]        ],        resize_keyboard=True, is_persistent=True    )class AdminStates(StatesGroup):    add_channel, del_channel = State(), State()    add_video_get, add_video_bacca, add_video_viral = State(), State(), State()    add_redeem = State()    bc_wait_media, bc_wait_token, bc_wait_link_media = State(), State(), State()    bcl_wait_caption, bcl_wait_price, bcl_wait_locked = State(), State(), State()    link_video_wait = State()class UserStates(StatesGroup):    redeem_wait_code = State()# ==================== USER HANDLERS ====================@router.message(Command("start"))async def cmd_start(msg: Message, state: FSMContext):    await state.clear()    uid, name, uname = msg.from_user.id, msg.from_user.full_name, msg.from_user.username or ""    if not await is_bot_on() and uid != OWNER_ID:        return await msg.answer("🔴 𝐁𝐨𝐭 𝐢𝐬 𝐜𝐮𝐫𝐫𝐞𝐧𝐭𝐥𝐲 𝐎𝐅𝐅.")    refer_id = None    parts = msg.text.split()    if len(parts) > 1 and parts[1].startswith("ref_"):        try: refer_id = int(parts[1][4:])        except ValueError: pass    async with DB.execute("SELECT user_id FROM users WHERE user_id=?", (uid,)) as cur:        existed = await cur.fetchone()    user = await get_user(uid)    await update_user_name(uid, name, uname)    if not existed:        if refer_id and refer_id != uid:            async with DB.execute("SELECT user_id FROM users WHERE user_id=?", (refer_id,)) as cur:                if await cur.fetchone():                    await DB.execute("UPDATE users SET refer_by=?, refer_count=refer_count+1 WHERE user_id=?", (refer_id, uid))                    await add_token(refer_id, TOKEN_REFER_BONUS)                    try: await bot.send_message(refer_id, f"🎉 <b>𝐍𝐄𝐖 𝐑𝐄𝐅𝐄𝐑𝐑𝐀𝐋!</b>\n➕ {TOKEN_REFER_BONUS} 𝐓𝐎𝐊𝐄𝐍𝐒 𝐀𝐃𝐃𝐄𝐃.")                    except Exception: pass        try: await bot.send_message(OWNER_ID, f"🆕 <b>𝐍𝐄𝐖 𝐔𝐒𝐄𝐑</b>\n\n👤 𝐍𝐀𝐌𝐄: {name}\n🔗 𝐔𝐒𝐄𝐑: @{uname if uname else '𝐍𝐎𝐍𝐄'}\n🆔 𝐈𝐃: <code>{uid}</code>")        except Exception: pass    # ✅ Link-video ব্যাচ চেক    if len(parts) > 1 and parts[1].startswith("lv_"):        if await is_user_joined_all(uid):            await deliver_link_batch(msg, parts[1])        else:            await msg.answer(                "🔒 <b>𝐅𝐎𝐑𝐂𝐄 𝐉𝐎𝐈𝐍</b>\n\n𝐏𝐥𝐞𝐚𝐬𝐞 𝐣𝐨𝐢𝐧 𝐭𝐡𝐞 𝐜𝐡𝐚𝐧𝐧𝐞𝐥𝐬 𝐛𝐞𝐥𝐨𝐰 𝐚𝐧𝐝 𝐭𝐚𝐩 𝐂𝐡𝐞𝐜𝐤 𝐉𝐨𝐢𝐧.",                reply_markup=await force_join_keyboard_for(uid)            )        return    if not await is_user_joined_all(uid):        return await msg.answer(            "🔒 <b>𝐅𝐎𝐑𝐂𝐄 𝐉𝐎𝐈𝐍</b>\n\n𝐏𝐥𝐞𝐚𝐬𝐞 𝐣𝐨𝐢𝐧 𝐭𝐡𝐞 𝐜𝐡𝐚𝐧𝐧𝐞𝐥𝐬 𝐛𝐞𝐥𝐨𝐰 𝐚𝐧𝐝 𝐭𝐚𝐩 𝐂𝐡𝐞𝐜𝐤 𝐉𝐨𝐢𝐧.",            reply_markup=await force_join_keyboard_for(uid)        )    await msg.answer(        f"♥️ <b>𝐖𝐄𝐋𝐂𝐎𝐌𝐄</b> ♥️\n\n👤 <b>𝐍𝐀𝐌𝐄:</b> {name}\n🆔 <b>𝐈𝐃:</b> <code>{uid}</code>\n💰 <b>𝐁𝐀𝐋𝐀𝐍𝐂𝐄:</b> {user['tokens']} 𝐓𝐎𝐊𝐄𝐍𝐒\n\n✨ <i>𝐂𝐡𝐨𝐨𝐬𝐞 𝐚𝐧 𝐨𝐩𝐭𝐢𝐨𝐧 𝐛𝐞𝐥𝐨𝐰</i> 👇",        reply_markup=home_keyboard()    )@router.callback_query(F.data == "check_join")async def cb_check_join(cb: CallbackQuery):    uid = cb.from_user.id    if await is_user_joined_all(uid):        user = await get_user(uid)        try:            await cb.message.edit_text(f"✅ <b>𝐀𝐋𝐋 𝐂𝐇𝐀𝐍𝐍𝐄𝐋𝐒 𝐉𝐎𝐈𝐍𝐄𝐃!</b>\n\n💰 <b>𝐁𝐀𝐋𝐀𝐍𝐂𝐄:</b> {user['tokens']} 𝐓𝐎𝐊𝐄𝐍𝐒")        except Exception: pass        await cb.message.answer("𝐌𝐄𝐍𝐔:", reply_markup=home_keyboard())    else:        await cb.answer("❌ 𝐘𝐎𝐔 𝐇𝐀𝐕𝐄 𝐍𝐎𝐓 𝐉𝐎𝐈𝐍𝐄𝐃 𝐀𝐋𝐋 𝐂𝐇𝐀𝐍𝐍𝐄𝐋𝐒 𝐘𝐄𝐓!", show_alert=True)        try:            await cb.message.edit_reply_markup(reply_markup=await force_join_keyboard_for(uid))        except Exception: pass@router.chat_join_request()async def handle_join_request(request: ChatJoinRequest):    user_id = request.from_user.id    chat_id = str(request.chat.id)    await DB.execute("INSERT OR IGNORE INTO pending_joins(user_id, chat_id) VALUES(?,?)", (user_id, chat_id))    await DB.commit()@router.message(F.text == "💰 𝐁𝐀𝐋𝐀𝐍𝐂𝐄")async def btn_balance(msg: Message):    if not await require_join(msg): return    user = await get_user(msg.from_user.id)    await msg.answer(f"💰 <b>𝐘𝐎𝐔𝐑 𝐁𝐀𝐋𝐀𝐍𝐂𝐄</b>\n\n🪙 <b>𝐓𝐎𝐊𝐄𝐍𝐒:</b> {user['tokens']}\n👥 <b>𝐑𝐄𝐅𝐄𝐑𝐑𝐀𝐋𝐒:</b> {user['refer_count']}\n♥️ <b>𝐕𝐈𝐃𝐄𝐎𝐒 𝐖𝐀𝐓𝐂𝐇𝐄𝐃:</b> {user['videos_seen']}", reply_markup=home_keyboard())@router.message(F.text == "🛒 𝐁𝐔𝐘 𝐓𝐎𝐊𝐄𝐍")async def btn_buy(msg: Message):    if not await require_join(msg): return    kb = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="💬 𝐂𝐎𝐍𝐓𝐀𝐂𝐓 𝐎𝐖𝐍𝐄𝐑", url="https://t.me/Jara_chat_bot")]])    await msg.answer("🛒 <b>𝐁𝐔𝐘 𝐓𝐎𝐊𝐄𝐍</b>\n\n💬 𝐓𝐨 𝐛𝐮𝐲 𝐭𝐨𝐤𝐞𝐧𝐬, 𝐜𝐨𝐧𝐭𝐚𝐜𝐭:\n👉 <b>@Jara_chat_bot</b>", reply_markup=kb)@router.message(F.text == "🔗 𝐑𝐄𝐅𝐄𝐑")async def btn_refer(msg: Message):    if not await require_join(msg): return    uid, me = msg.from_user.id, await bot.get_me()    user = await get_user(uid)    await msg.answer(f"🔗 <b>𝐑𝐄𝐅𝐄𝐑 & 𝐄𝐀𝐑𝐍</b>\n\n🔗 <b>𝐘𝐎𝐔𝐑 𝐋𝐈𝐍𝐊:</b>\n<code>https://t.me/{me.username}?start=ref_{uid}</code>\n\n🎁 <b>𝐏𝐄𝐑 𝐑𝐄𝐅𝐄𝐑:</b> {TOKEN_REFER_BONUS} 𝐓𝐎𝐊𝐄𝐍𝐒\n👥 <b>𝐓𝐎𝐓𝐀𝐋 𝐑𝐄𝐅𝐄𝐑𝐑𝐀𝐋𝐒:</b> {user['refer_count']}", reply_markup=home_keyboard())@router.message(F.text == "🎁 𝐑𝐄𝐃𝐄𝐄𝐌")async def btn_redeem(msg: Message, state: FSMContext):    if not await require_join(msg): return    await state.set_state(UserStates.redeem_wait_code)    await msg.answer("🎁 <b>𝐑𝐄𝐃𝐄𝐄𝐌 𝐂𝐎𝐃𝐄</b>\n\n📝 𝐏𝐥𝐞𝐚𝐬𝐞 𝐬𝐞𝐧𝐝 𝐲𝐨𝐮𝐫 𝐫𝐞𝐝𝐞𝐞𝐦 𝐜𝐨𝐝𝐞:", reply_markup=home_keyboard())@router.message(UserStates.redeem_wait_code)async def user_redeem_code(msg: Message, state: FSMContext):    await state.clear()    if not await require_join(msg): return    async with DB.execute("SELECT * FROM redeem WHERE code=?", (msg.text.strip(),)) as cur:        row = await cur.fetchone()    if not row: return await msg.answer("❌ 𝐈𝐍𝐕𝐀𝐋𝐈𝐃 𝐎𝐑 𝐔𝐍𝐔𝐒𝐄𝐃 𝐂𝐎𝐃𝐄.", reply_markup=home_keyboard())    if row["used_by"]: return await msg.answer("❌ 𝐓𝐇𝐈𝐒 𝐂𝐎𝐃𝐄 𝐇𝐀𝐒 𝐀𝐋𝐑𝐄𝐀𝐃𝐘 𝐁𝐄𝐄𝐍 𝐔𝐒𝐄𝐃.", reply_markup=home_keyboard())    await DB.execute("UPDATE redeem SET used_by=? WHERE code=?", (msg.from_user.id, msg.text.strip()))    await add_token(msg.from_user.id, row["tokens"])    await msg.answer(f"✅ <b>𝐑𝐄𝐃𝐄𝐄𝐌 𝐒𝐔𝐂𝐂𝐄𝐒𝐒𝐅𝐔𝐋!</b>\n\n➕ {row['tokens']} 𝐓𝐎𝐊𝐄𝐍𝐒 𝐀𝐃𝐃𝐄𝐃.", reply_markup=home_keyboard())# ==================== VIDEO & VIP ====================@router.message(F.text == "📸 𝐆𝐄𝐓 𝐕𝐈𝐃𝐄𝐎")async def btn_get_video(msg: Message):    if not await require_join(msg): return    uid = msg.from_user.id    async with user_locks[uid]:        user = await get_user(uid)        if user["tokens"] < TOKEN_GET_VIDEO:            return await msg.answer(f"❌ 𝐘𝐨𝐮 𝐧𝐞𝐞𝐝 {TOKEN_GET_VIDEO} 𝐭𝐨𝐤𝐞𝐧!", reply_markup=home_keyboard())        async with DB.execute("SELECT * FROM videos ORDER BY id ASC") as cur:            all_v = [dict(r) async for r in cur]        if not all_v:            return await msg.answer("❌ 𝐍𝐨 𝐯𝐢𝐝𝐞𝐨𝐬 𝐡𝐚𝐯𝐞 𝐛𝐞𝐞𝐧 𝐬𝐞𝐭 𝐲𝐞𝐭.", reply_markup=home_keyboard())        idx = user["videos_seen"]        if idx >= len(all_v):            kb = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="🔄 𝐖𝐀𝐓𝐂𝐇 𝐀𝐆𝐀𝐈𝐍", callback_data="reset_seen")]])            return await msg.answer("✅ <b>𝐀𝐥𝐥 𝐯𝐢𝐝𝐞𝐨𝐬 𝐡𝐚𝐯𝐞 𝐛𝐞𝐞𝐧 𝐝𝐞𝐥𝐢𝐯𝐞𝐫𝐞𝐝!</b>\n\n🔄 𝐓𝐚𝐩 𝐛𝐞𝐥𝐨𝐰 𝐭𝐨 𝐰𝐚𝐭𝐜𝐡 𝐚𝐠𝐚𝐢𝐧 👇", reply_markup=kb)        vid = all_v[idx]        if not await deduct_token(uid, TOKEN_GET_VIDEO):            return await msg.answer("❌ 𝐍𝐨𝐭 𝐞𝐧𝐨𝐮𝐠𝐡 𝐭𝐨𝐤𝐞𝐧𝐬!", reply_markup=home_keyboard())        await DB.execute("UPDATE users SET videos_seen=videos_seen+1 WHERE user_id=?", (uid,))        await DB.commit()    try:        if vid["vtype"] == "video": sent = await bot.send_video(uid, vid["file_id"], caption=vid["caption"] or "", protect_content=True)        else: sent = await bot.send_photo(uid, vid["file_id"], caption=vid["caption"] or "", protect_content=True)        delete_at = datetime.utcnow() + timedelta(minutes=VIDEO_DELETE_MIN)        warn = await bot.send_message(uid, f"➥ 𝚃𝚑𝚒𝚜 𝙼𝚊𝚜𝚜𝚊𝚐𝚎 𝚆𝚒𝚕𝚕 𝙱𝚎 𝙳𝚎𝚕𝚎𝚝𝚎𝚍 𝙸𝚗 {VIDEO_DELETE_MIN} 𝙼𝚒𝚗𝚞𝚝𝚎𝚜.")        await schedule_delete(uid, sent.message_id, delete_at)        await schedule_delete(uid, warn.message_id, delete_at)    except Exception as e:        log.error(f"Get Video Error: {e}")        await add_token(uid, TOKEN_GET_VIDEO)        await msg.answer("❌ 𝐄𝐫𝐫𝐨𝐫, 𝐭𝐨𝐤𝐞𝐧 𝐫𝐞𝐟𝐮𝐧𝐝𝐞𝐝.", reply_markup=home_keyboard())@router.callback_query(F.data == "reset_seen")async def cb_reset_seen(cb: CallbackQuery):    if not await require_join(cb): return    await DB.execute("UPDATE users SET videos_seen=0 WHERE user_id=?", (cb.from_user.id,))    await DB.commit()    await cb.answer("🔄 𝐑𝐞𝐬𝐞𝐭 𝐝𝐨𝐧𝐞! 𝐓𝐚𝐩 𝐆𝐄𝐓 𝐕𝐈𝐃𝐄𝐎 𝐚𝐠𝐚𝐢𝐧.", show_alert=True)@router.message(F.text == "👑 𝐕𝐈𝐏 𝐕𝐈𝐃𝐄𝐎")async def btn_vip_menu(msg: Message):    if not await require_join(msg): return    kb = InlineKeyboardMarkup(inline_keyboard=[        [InlineKeyboardButton(text=f"🔞 𝐁𝐀𝐂𝐂𝐀 ({TOKEN_BACCA} 𝐓𝐨𝐤𝐞𝐧𝐬)", callback_data="vip_bacca")],        [InlineKeyboardButton(text=f"🔥 𝐕𝐈𝐑𝐀𝐋+𝐕𝐈𝐏 ({TOKEN_VIRAL_VIP} 𝐓𝐨𝐤𝐞𝐧𝐬)", callback_data="vip_viral")]    ])    await msg.answer("👑 <b>𝐕𝐈𝐏 𝐕𝐈𝐃𝐄𝐎</b>\n\n✨ <i>𝐂𝐡𝐨𝐨𝐬𝐞 𝐚 𝐩𝐥𝐚𝐧 𝐛𝐞𝐥𝐨𝐰</i> 👇", reply_markup=kb)async def send_vip(cb: CallbackQuery, plan: str, price: int):    if not await require_join(cb): return    uid = cb.from_user.id    async with user_locks[uid]:        if not await deduct_token(uid, price):            return await cb.answer(f"❌ 𝐘𝐨𝐮 𝐧𝐞𝐞𝐝 {price} 𝐭𝐨𝐤𝐞𝐧𝐬!", show_alert=True)        async with DB.execute("SELECT * FROM vip_videos WHERE plan=? ORDER BY RANDOM() LIMIT 1", (plan,)) as cur:            vid = await cur.fetchone()        if not vid:            await add_token(uid, price)            return await cb.answer("❌ 𝐍𝐨 𝐯𝐢𝐝𝐞𝐨 𝐬𝐞𝐭 𝐟𝐨𝐫 𝐭𝐡𝐢𝐬 𝐩𝐥𝐚𝐧.", show_alert=True)    try:        if vid["vtype"] == "video": sent = await bot.send_video(uid, vid["file_id"], caption=vid["caption"] or "", protect_content=True)        else: sent = await bot.send_photo(uid, vid["file_id"], caption=vid["caption"] or "", protect_content=True)        delete_at = datetime.utcnow() + timedelta(minutes=VIP_VIDEO_DELETE_MIN)        warn = await bot.send_message(uid, f"➥ 𝚃𝚑𝚒𝚜 𝙼𝚊𝚜𝚜𝚊𝚐𝚎 𝚆𝚒𝚕𝚕 𝙱𝚎 𝙳𝚎𝚕𝚎𝚝𝚎𝚍 𝙸𝚗 {VIP_VIDEO_DELETE_MIN} 𝙼𝚒𝚗𝚞𝚝𝚎𝚜.")        await schedule_delete(uid, sent.message_id, delete_at)        await schedule_delete(uid, warn.message_id, delete_at)        await cb.answer("✅ 𝐕𝐈𝐏 𝐯𝐢𝐝𝐞𝐨 𝐬𝐞𝐧𝐭!")    except Exception as e:        log.error(f"VIP Send Error: {e}")        await add_token(uid, price)        await cb.answer("❌ 𝐄𝐫𝐫𝐨𝐫, 𝐭𝐨𝐤𝐞𝐧 𝐫𝐞𝐟𝐮𝐧𝐝𝐞𝐝.", show_alert=True)@router.callback_query(F.data == "vip_bacca")async def cb_vip_bacca(cb: CallbackQuery): await send_vip(cb, "bacca", TOKEN_BACCA)@router.callback_query(F.data == "vip_viral")async def cb_vip_viral(cb: CallbackQuery): await send_vip(cb, "viral", TOKEN_VIRAL_VIP)# ==================== BACKUP / RESTORE ====================@router.message(Command("backup"))async def cmd_backup(msg: Message):    if msg.from_user.id != OWNER_ID: return await msg.answer("❌ 𝐎𝐰𝐧𝐞𝐫 𝐨𝐧𝐥𝐲.")    try:        await DB.execute("PRAGMA wal_checkpoint(FULL)")        await DB.commit()        backup_name = f"/app/data/backup_{datetime.utcnow().strftime('%Y%m%d_%H%M%S')}.db"        shutil.copyfile(DB_FILE, backup_name)        doc = FSInputFile(backup_name, filename=os.path.basename(backup_name))        await msg.answer_document(doc, caption="✅ 𝐁𝐚𝐜𝐤𝐮𝐩 𝐜𝐨𝐦𝐩𝐥𝐞𝐭𝐞!\n\n💡 𝐑𝐞𝐬𝐭𝐨𝐫𝐞 𝐤𝐨𝐫𝐭𝐞 𝐞𝐢 𝐟𝐢𝐥𝐞 𝐫𝐢𝐩𝐥𝐚𝐲 𝐤𝐨𝐫𝐞 <code>/restore</code> 𝐥𝐢𝐤𝐡𝐮𝐧।")        try: os.remove(backup_name)        except: pass    except Exception as e:        log.error(f"backup error: {e}")        await msg.answer(f"❌ 𝐁𝐚𝐜𝐤𝐮𝐩 𝐟𝐚𝐢𝐥𝐞𝐝: {e}")@router.message(Command("restore"))async def cmd_restore(msg: Message):    global DB    if msg.from_user.id != OWNER_ID: return await msg.answer("❌ 𝐎𝐰𝐧𝐞𝐫 𝐨𝐧𝐥𝐲.")    if not msg.reply_to_message or not msg.reply_to_message.document:        return await msg.answer("❌ <b>𝐁𝐚𝐜𝐤𝐮𝐩 𝐟𝐢𝐥𝐞 𝐞𝐫 𝐫𝐢𝐩𝐥𝐚𝐲 𝐝𝐢𝐲𝐞</b> <code>/restore</code> 𝐥𝐢𝐤𝐡𝐮𝐧।")    doc = msg.reply_to_message.document    if not doc.file_name or not doc.file_name.endswith(".db"):        return await msg.answer("❌ 𝐎𝐧𝐥𝐲 <b>.db</b> 𝐛𝐚𝐜𝐤𝐮𝐩 𝐟𝐢𝐥𝐞 𝐚𝐜𝐜𝐞𝐩𝐭𝐞𝐝।")    status = await msg.answer("⏳ 𝐑𝐞𝐬𝐭𝐨𝐫𝐢𝐧𝐠...")    tmp = f"/app/data/restore_{datetime.utcnow().strftime('%Y%m%d_%H%M%S')}.db"    try:        f = await bot.get_file(doc.file_id)        await bot.download_file(f.file_path, tmp)        await DB.close()        try:            if os.path.exists(DB_FILE): os.remove(DB_FILE)            for ext in ("-wal", "-shm"):                if os.path.exists(DB_FILE + ext): os.remove(DB_FILE + ext)        except: pass        shutil.move(tmp, DB_FILE)        DB = await aiosqlite.connect(DB_FILE)        DB.row_factory = aiosqlite.Row        await DB.execute("PRAGMA journal_mode=WAL")        await DB.execute("PRAGMA synchronous=NORMAL")        await DB.execute("PRAGMA busy_timeout=8000")        await DB.execute("PRAGMA cache_size=-64000")        await DB.execute("PRAGMA temp_store=MEMORY")        await DB.commit()        await status.edit_text("✅ <b>𝐑𝐞𝐬𝐭𝐨𝐫𝐞 𝐜𝐨𝐦𝐩𝐥𝐞𝐭𝐞!</b>\n\nসব ডাটা ফিরে এসেছে।")    except Exception as e:        log.error(f"restore error: {e}")        try: os.remove(tmp)        except: pass        try:            if not DB or DB._closed:                DB = await aiosqlite.connect(DB_FILE)                DB.row_factory = aiosqlite.Row        except: pass        await status.edit_text(f"❌ 𝐑𝐞𝐬𝐭𝐨𝐫𝐞 𝐟𝐚𝐢𝐥𝐞𝐝: {e}")# ==================== LINK-VIDEO SYSTEM ====================@router.message(Command("link-video"))async def cmd_link_video(msg: Message, state: FSMContext):    if msg.from_user.id != OWNER_ID: return await msg.answer("❌ 𝐎𝐰𝐧𝐞𝐫 𝐨𝐧𝐥𝐲.")    await state.clear()    await state.set_state(AdminStates.link_video_wait)    await state.update_data(lv_items=[])    kb = InlineKeyboardMarkup(inline_keyboard=[        [InlineKeyboardButton(text="✅ 𝐂𝐎𝐍𝐅𝐈𝐑𝐌 & 𝐆𝐄𝐓 𝐋𝐈𝐍𝐊", callback_data="lv_confirm")],        [InlineKeyboardButton(text="❌ 𝐂𝐀𝐍𝐂𝐄𝐋", callback_data="lv_cancel")]    ])    await msg.answer(        "🔗 <b>𝐋𝐈𝐍𝐊-𝐕𝐈𝐃𝐄𝐎 𝐒𝐄𝐓𝐔𝐏</b>\n\n"        "𝐄𝐤𝐭𝐚 𝐞𝐤𝐭𝐚 𝐤𝐨𝐫𝐞 𝐯𝐢𝐝𝐞𝐨 / 𝐩𝐡𝐨𝐭𝐨 / 𝐭𝐞𝐱𝐭 / 𝐚𝐮𝐝𝐢𝐨 𝐩𝐚𝐭𝐡𝐚𝐧।\n"        "সব দেওয়া শেষ হলে <b>✅ CONFIRM</b> চাপুন।\n\n"        "❌ 𝐂𝐚𝐧𝐜𝐞𝐥: /cancel",        reply_markup=kb    )@router.message(AdminStates.link_video_wait)async def lv_collect(msg: Message, state: FSMContext):    if msg.from_user.id != OWNER_ID: return    if msg.text == "/cancel":        await state.clear()        return await msg.answer("❌ 𝐂𝐚𝐧𝐜𝐞𝐥𝐥𝐞𝐝।", reply_markup=admin_keyboard())    data = await state.get_data()    items = data.get("lv_items", [])    item = None    if msg.video: item = ("video", msg.video.file_id, msg.caption or "")    elif msg.photo: item = ("photo", msg.photo[-1].file_id, msg.caption or "")    elif msg.audio: item = ("audio", msg.audio.file_id, msg.caption or "")    elif msg.text: item = ("text", None, msg.text)    if not item:        return await msg.answer("❌ 𝐒𝐞𝐧𝐝 𝐯𝐢𝐝𝐞𝐨/𝐩𝐡𝐨𝐭𝐨/𝐚𝐮𝐝𝐢𝐨/𝐭𝐞𝐱𝐭।")    items.append({"vtype": item[0], "file_id": item[1], "caption": item[2]})    await state.update_data(lv_items=items)    kb = InlineKeyboardMarkup(inline_keyboard=[        [InlineKeyboardButton(text=f"✅ 𝐂𝐎𝐍𝐅𝐈𝐑𝐌 ({len(items)} 𝐢𝐭𝐞𝐦𝐬) & 𝐆𝐄𝐓 𝐋𝐈𝐍𝐊", callback_data="lv_confirm")],        [InlineKeyboardButton(text="❌ 𝐂𝐀𝐍𝐂𝐄𝐋", callback_data="lv_cancel")]    ])    await msg.answer(f"✅ 𝐀𝐝𝐝𝐞𝐝 ({len(items)} 𝐭𝐨𝐭𝐚𝐥)। 𝐀𝐫𝐨 𝐩𝐚𝐭𝐡𝐚𝐧 𝐨𝐫 𝐂𝐎𝐍𝐅𝐈𝐑𝐌 𝐜𝐡𝐚𝐩𝐮𝐧।", reply_markup=kb)@router.callback_query(F.data == "lv_cancel")async def cb_lv_cancel(cb: CallbackQuery, state: FSMContext):    if cb.from_user.id != OWNER_ID: return    await state.clear()    try: await cb.message.edit_text("❌ 𝐂𝐚𝐧𝐜𝐞𝐥𝐥𝐞𝐝।")    except: pass    await cb.message.answer("🛠 𝐀𝐃𝐌𝐈𝐍 𝐏𝐀𝐍𝐄𝐋", reply_markup=admin_keyboard())@router.callback_query(F.data == "lv_confirm")async def cb_lv_confirm(cb: CallbackQuery, state: FSMContext):    if cb.from_user.id != OWNER_ID: return    data = await state.get_data()    items = data.get("lv_items", [])    if not items:        return await cb.answer("❌ 𝐍𝐨 𝐢𝐭𝐞𝐦𝐬 𝐚𝐝𝐝𝐞𝐝!", show_alert=True)    batch_id = f"lv_{int(datetime.utcnow().timestamp())}_{cb.from_user.id}"    now = datetime.utcnow().isoformat()    await DB.execute("INSERT INTO link_batches(batch_id, owner_id, created) VALUES(?,?,?)", (batch_id, cb.from_user.id, now))    for it in items:        await DB.execute(            "INSERT INTO link_videos(batch_id, file_id, vtype, caption, added_at) VALUES(?,?,?,?,?)",            (batch_id, it["file_id"], it["vtype"], it["caption"], now)        )    await DB.commit()    await state.clear()    me = await bot.get_me()    link = f"https://t.me/{me.username}?start={batch_id}"    kb = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="📤 𝐒𝐇𝐀𝐑𝐄 𝐋𝐈𝐍𝐊", url=f"https://t.me/share/url?url={link}")]])    try:        await cb.message.edit_text(            f"✅ <b>𝐋𝐈𝐍𝐊 𝐂𝐑𝐄𝐀𝐓𝐄𝐃!</b>\n\n"            f"📦 𝐈𝐭𝐞𝐦𝐬: {len(items)}\n\n"            f"🔗 <b>𝐘𝐎𝐔𝐑 𝐋𝐈𝐍𝐊:</b>\n<code>{link}</code>\n\n"            f"👆 এই লিংকে কেউ ক্লিক করলে force join চেক হয়ে সব কন্টেন্ট পাবে।",            reply_markup=kb        )    except: passasync def deliver_link_batch(msg: Message, batch_id: str):    uid = msg.from_user.id    async with DB.execute("SELECT * FROM link_videos WHERE batch_id=? ORDER BY id ASC", (batch_id,)) as cur:        rows = [dict(r) async for r in cur]    if not rows:        return await msg.answer("❌ 𝐓𝐡𝐢𝐬 𝐥𝐢𝐧𝐤 𝐢𝐬 𝐞𝐦𝐩𝐭𝐲 𝐨𝐫 𝐢𝐧𝐯𝐚𝐥𝐢𝐝.", reply_markup=home_keyboard())    await msg.answer(f"📦 <b>𝐃𝐄𝐋𝐈𝐕𝐄𝐑𝐈𝐍𝐆 {len(rows)} 𝐈𝐓𝐄𝐌𝐒...</b>", reply_markup=home_keyboard())    for r in rows:        try:            if r["vtype"] == "video":                await bot.send_video(uid, r["file_id"], caption=r["caption"] or "", protect_content=True)            elif r["vtype"] == "photo":                await bot.send_photo(uid, r["file_id"], caption=r["caption"] or "", protect_content=True)            elif r["vtype"] == "audio":                await bot.send_audio(uid, r["file_id"], caption=r["caption"] or "", protect_content=True)            else:                if r["caption"]:                    await bot.send_message(uid, r["caption"], protect_content=True)            await asyncio.sleep(0.08)        except Exception as e:            log.error(f"deliver_link_batch item error: {e}")# ==================== ADMIN PANEL ====================def admin_keyboard() -> InlineKeyboardMarkup:    return InlineKeyboardMarkup(inline_keyboard=[        [InlineKeyboardButton(text="📸 𝐀𝐃𝐃 𝐕𝐈𝐃𝐄𝐎", callback_data="adm_add_video"), InlineKeyboardButton(text="👑 𝐀𝐃𝐃 𝐕𝐈𝐏", callback_data="adm_add_vip")],        [InlineKeyboardButton(text="📢 𝐉𝐎𝐈𝐍 𝐒𝐄𝐓", callback_data="adm_join_set"), InlineKeyboardButton(text="🎁 𝐑𝐄𝐃𝐄𝐄𝐌", callback_data="adm_redeem")],        [InlineKeyboardButton(text="📣 𝐁𝐑𝐎𝐀𝐃𝐂𝐀𝐒𝐓", callback_data="adm_broadcast"), InlineKeyboardButton(text="🔗 𝐁𝐂-𝐋𝐈𝐍𝐊𝐒", callback_data="adm_bc_links")],        [InlineKeyboardButton(text="📊 𝐒𝐓𝐀𝐓𝐒", callback_data="adm_stats")],        [InlineKeyboardButton(text="🔌 𝐁𝐎𝐓 𝐎𝐍/𝐎𝐅𝐅", callback_data="adm_bot_toggle")]    ])def owner_only(cb: CallbackQuery) -> bool: return cb.from_user.id == OWNER_ID@router.message(Command("admin"))async def cmd_admin(msg: Message):    if msg.from_user.id != OWNER_ID: return await msg.answer("❌ 𝐎𝐰𝐧𝐞𝐫 𝐨𝐧𝐥𝐲.")    await msg.answer("🛠 <b>𝐀𝐃𝐌𝐈𝐍 𝐏𝐀𝐍𝐄𝐋</b>", reply_markup=admin_keyboard())@router.callback_query(F.data == "adm_back")async def cb_adm_back(cb: CallbackQuery, state: FSMContext):    if not owner_only(cb): return    await state.clear()    await cb.message.edit_text("🛠 <b>𝐀𝐃𝐌𝐈𝐍 𝐏𝐀𝐍𝐄𝐋</b>", reply_markup=admin_keyboard())# ---- Stats ----@router.callback_query(F.data == "adm_stats")async def cb_adm_stats(cb: CallbackQuery):    if not owner_only(cb): return    async with DB.execute("SELECT COUNT(*) AS c FROM users") as cur:        total_users = (await cur.fetchone())["c"]    async with DB.execute("SELECT COUNT(*) AS c FROM users WHERE is_banned=1") as cur:        banned = (await cur.fetchone())["c"]    async with DB.execute("SELECT COALESCE(SUM(tokens),0) AS s FROM users") as cur:        total_tokens = (await cur.fetchone())["s"]    async with DB.execute("SELECT COUNT(*) AS c FROM videos") as cur:        total_videos = (await cur.fetchone())["c"]    async with DB.execute("SELECT COUNT(*) AS c FROM vip_videos") as cur:        total_vip = (await cur.fetchone())["c"]    async with DB.execute("SELECT COUNT(*) AS c FROM channels") as cur:        total_channels = (await cur.fetchone())["c"]    async with DB.execute("SELECT COUNT(*) AS c FROM link_batches") as cur:        total_link_batches = (await cur.fetchone())["c"]    async with DB.execute("SELECT COUNT(*) AS c FROM link_videos") as cur:        total_link_items = (await cur.fetchone())["c"]    async with DB.execute("SELECT COUNT(*) AS c FROM broadcast") as cur:        total_bc = (await cur.fetchone())["c"]    async with DB.execute("SELECT COUNT(*) AS c FROM broadcast_links") as cur:        total_bcl = (await cur.fetchone())["c"]    active = total_users - banned    text = (        "📊 <b>𝐁𝐎𝐓 𝐒𝐓𝐀𝐓𝐒</b>\n\n"        f"👥 <b>𝐓𝐨𝐭𝐚𝐥 𝐔𝐬𝐞𝐫𝐬:</b> {total_users}\n"        f"🟢 <b>𝐀𝐜𝐭𝐢𝐯𝐞:</b> {active}\n"        f"🔴 <b>𝐁𝐚𝐧𝐧𝐞𝐝:</b> {banned}\n\n"        f"🪙 <b>𝐓𝐨𝐭𝐚𝐥 𝐓𝐨𝐤𝐞𝐧𝐬 𝐢𝐧 𝐜𝐢𝐫𝐜𝐮𝐥𝐚𝐭𝐢𝐨𝐧:</b> {total_tokens}\n\n"        f"📸 <b>𝐕𝐢𝐝𝐞𝐨𝐬:</b> {total_videos}\n"        f"👑 <b>𝐕𝐈𝐏 𝐕𝐢𝐝𝐞𝐨𝐬:</b> {total_vip}\n"        f"📢 <b>𝐉𝐨𝐢𝐧 𝐂𝐡𝐚𝐧𝐧𝐞𝐥𝐬:</b> {total_channels}\n\n"        f"🔗 <b>𝐋𝐢𝐧𝐤 𝐁𝐚𝐭𝐜𝐡𝐞𝐬:</b> {total_link_batches}\n"        f"📦 <b>𝐋𝐢𝐧𝐤 𝐈𝐭𝐞𝐦𝐬:</b> {total_link_items}\n\n"        f"📣 <b>𝐁𝐫𝐨𝐚𝐝𝐜𝐚𝐬𝐭𝐬:</b> {total_bc}\n"        f"🔗 <b>𝐁𝐂-𝐋𝐢𝐧𝐤𝐬:</b> {total_bcl}"    )    try:        await cb.message.edit_text(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="🔄 𝐑𝐞𝐟𝐫𝐞𝐬𝐡", callback_data="adm_stats")], [InlineKeyboardButton(text="⬅️ 𝐁𝐚𝐜𝐤", callback_data="adm_back")]]))    except Exception: pass    await cb.answer()# ---- Add Video ----@router.callback_query(F.data == "adm_add_video")async def cb_adm_add_video(cb: CallbackQuery, state: FSMContext):    if not owner_only(cb): return    await state.set_state(AdminStates.add_video_get)    await cb.message.edit_text("📸 <b>𝐀𝐝𝐝 𝐕𝐢𝐝𝐞𝐨</b>\n\n📤 𝐒𝐞𝐧𝐝 𝐯𝐢𝐝𝐞𝐨/𝐩𝐡𝐨𝐭𝐨:", reply_markup=InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="⬅️ 𝐁𝐚𝐜𝐤", callback_data="adm_back")]]))@router.message(AdminStates.add_video_get)async def adm_save_video(msg: Message, state: FSMContext):    if msg.from_user.id != OWNER_ID: return    if msg.video: fid, vt, cap = msg.video.file_id, "video", msg.caption or ""    elif msg.photo: fid, vt, cap = msg.photo[-1].file_id, "photo", msg.caption or ""    else: return await msg.answer("❌ 𝐒𝐞𝐧𝐝 𝐯𝐢𝐝𝐞𝐨/𝐩𝐡𝐨𝐭𝐨.")    await DB.execute("INSERT INTO videos(file_id,vtype,caption,added_at) VALUES(?,?,?,?)", (fid, vt, cap, datetime.utcnow().isoformat()))    await DB.commit()    await state.clear()    await msg.answer("✅ 𝐕𝐢𝐝𝐞𝐨 𝐚𝐝𝐝𝐞𝐝!", reply_markup=admin_keyboard())# ---- Add VIP ----@router.callback_query(F.data == "adm_add_vip")async def cb_adm_add_vip(cb: CallbackQuery):    if not owner_only(cb): return    kb = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="𝐁𝐀𝐂𝐂𝐀", callback_data="adm_vip_bacca")], [InlineKeyboardButton(text="𝐕𝐈𝐑𝐀𝐋+𝐕𝐈𝐏", callback_data="adm_vip_viral")], [InlineKeyboardButton(text="⬅️ 𝐁𝐚𝐜𝐤", callback_data="adm_back")]])    await cb.message.edit_text("👑 <b>𝐀𝐝𝐝 𝐕𝐈𝐏</b>\n\n𝐂𝐡𝐨𝐨𝐬𝐞 𝐚 𝐩𝐥𝐚𝐧:", reply_markup=kb)@router.callback_query(F.data == "adm_vip_bacca")async def cb_adm_vip_bacca(cb: CallbackQuery, state: FSMContext):    if not owner_only(cb): return    await state.set_state(AdminStates.add_video_bacca)    await cb.message.edit_text("🔞 𝐒𝐞𝐧𝐝 𝐁𝐀𝐂𝐂𝐀 𝐯𝐢𝐝𝐞𝐨/𝐩𝐡𝐨𝐭𝐨:")@router.callback_query(F.data == "adm_vip_viral")async def cb_adm_vip_viral(cb: CallbackQuery, state: FSMContext):    if not owner_only(cb): return    await state.set_state(AdminStates.add_video_viral)    await cb.message.edit_text("🔥 𝐒𝐞𝐧𝐝 𝐕𝐈𝐑𝐀𝐋+𝐕𝐈𝐏 𝐯𝐢𝐝𝐞𝐨/𝐩𝐡𝐨𝐭𝐨:")async def _save_vip(msg: Message, state: FSMContext, plan: str):    if msg.video: fid, vt, cap = msg.video.file_id, "video", msg.caption or ""    elif msg.photo: fid, vt, cap = msg.photo[-1].file_id, "photo", msg.caption or ""    else: return await msg.answer("❌ 𝐒𝐞𝐧𝐝 𝐯𝐢𝐝𝐞𝐨/𝐩𝐡𝐨𝐭𝐨.")    await DB.execute("INSERT INTO vip_videos(plan,file_id,vtype,caption,added_at) VALUES(?,?,?,?,?)", (plan, fid, vt, cap, datetime.utcnow().isoformat()))    await DB.commit()    await state.clear()    await msg.answer(f"✅ {plan.upper()} 𝐯𝐢𝐝𝐞𝐨 𝐚𝐝𝐝𝐞𝐝!", reply_markup=admin_keyboard())@router.message(AdminStates.add_video_bacca)async def adm_vip_bacca_save(msg: Message, state: FSMContext):    if msg.from_user.id == OWNER_ID: await _save_vip(msg, state, "bacca")@router.message(AdminStates.add_video_viral)async def adm_vip_viral_save(msg: Message, state: FSMContext):    if msg.from_user.id == OWNER_ID: await _save_vip(msg, state, "viral")# ---- Join Set ----@router.callback_query(F.data == "adm_join_set")async def cb_adm_join_set(cb: CallbackQuery):    if not owner_only(cb): return    kb = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="➕ 𝐒𝐞𝐭 𝐉𝐨𝐢𝐧", callback_data="adm_set_join")], [InlineKeyboardButton(text="📋 𝐋𝐢𝐬𝐭", callback_data="adm_join_list")], [InlineKeyboardButton(text="🗑 𝐃𝐞𝐥𝐞𝐭𝐞", callback_data="adm_join_delete")], [InlineKeyboardButton(text="⬅️ 𝐁𝐚𝐜𝐤", callback_data="adm_back")]])    await cb.message.edit_text("📢 <b>𝐉𝐨𝐢𝐧 𝐒𝐞𝐭</b>", reply_markup=kb)@router.callback_query(F.data == "adm_set_join")async def cb_adm_set_join(cb: CallbackQuery, state: FSMContext):    if not owner_only(cb): return    await state.set_state(AdminStates.add_channel)    await cb.message.edit_text(        "➕ <b>𝐒𝐞𝐭 𝐉𝐨𝐢𝐧</b>\n\n"        "𝐂𝐡𝐚𝐧𝐧𝐞𝐥/𝐆𝐫𝐨𝐮𝐩 𝐭𝐡𝐞𝐤𝐞 𝐞𝐤𝐭𝐢 𝐦𝐞𝐬𝐬𝐚𝐠𝐞 𝐛𝐨𝐭 𝐞 <b>𝐅𝐨𝐫𝐰𝐚𝐫𝐝</b> 𝐤𝐨𝐫𝐮𝐧.\n\n"        "💡 <b>𝐈𝐦𝐩𝐨𝐫𝐭𝐚𝐧𝐭:</b>\n"        "𝟏. 𝐁𝐨𝐭 𝐤𝐞 𝐜𝐡𝐚𝐧𝐧𝐞𝐥/𝐠𝐫𝐨𝐮𝐩 𝐞 <b>𝐀𝐝𝐦𝐢𝐧</b> 𝐤𝐨𝐫𝐮𝐧.\n"        "𝟐. 𝐏𝐫𝐢𝐯𝐚𝐭𝐞 𝐜𝐡𝐚𝐧𝐧𝐞𝐥 𝐡𝐨𝐥𝐞 'Invite Users via Link' 𝐩𝐞𝐫𝐦𝐢𝐬𝐬𝐢𝐨𝐧 𝐝𝐢𝐧.\n"        "𝟑. 𝐂𝐡𝐚𝐧𝐧𝐞𝐥/𝐆𝐫𝐨𝐮𝐩 𝐞𝐫 𝐲𝐞𝐤𝐨𝐧𝐨 𝐦𝐞𝐬𝐬𝐚𝐠𝐞 𝐅𝐨𝐫𝐰𝐚𝐫𝐝 𝐤𝐨𝐫𝐮𝐧."    )@router.message(AdminStates.add_channel)async def adm_add_channel(msg: Message, state: FSMContext):    if msg.from_user.id != OWNER_ID: return    if not msg.forward_from_chat:        return await msg.answer("❌ <b>𝐄𝐤𝐭𝐢 𝐦𝐞𝐬𝐬𝐚𝐠𝐞 𝐅𝐨𝐫𝐰𝐚𝐫𝐝 𝐤𝐨𝐫𝐮𝐧 (𝐂𝐡𝐚𝐧𝐧𝐞𝐥/𝐆𝐫𝐨𝐮𝐩 𝐭𝐡𝐞𝐤𝐞).</b>")    chat = msg.forward_from_chat    chat_id = str(chat.id)    title = chat.title or "Channel/Group"    try:        bot_member = await bot.get_chat_member(chat_id, bot.id)        if bot_member.status not in (ChatMemberStatus.ADMINISTRATOR, ChatMemberStatus.MEMBER):            return await msg.answer("❌ <b>𝐁𝐨𝐭 𝐤𝐞 𝐩𝐫𝐨𝐭𝐡𝐨𝐦𝐞 𝐜𝐡𝐚𝐧𝐧𝐞𝐥/𝐠𝐫𝐨𝐮𝐩 𝐞 𝐀𝐝𝐦𝐢𝐧 𝐤𝐨𝐫𝐮𝐧!</b>")        if bot_member.status == ChatMemberStatus.MEMBER and chat.type == "channel":            return await msg.answer("❌ <b>𝐁𝐨𝐭 𝐤𝐞 𝐜𝐡𝐚𝐧𝐧𝐞𝐥 𝐞 𝐀𝐝𝐦𝐢𝐧 𝐤𝐨𝐫𝐮𝐧 (𝐌𝐞𝐦𝐛𝐞𝐫 𝐧𝐨𝐲)!</b>")    except Exception as e:        return await msg.answer(f"❌ <b>𝐁𝐨𝐭 𝐤𝐞 𝐜𝐡𝐚𝐧𝐧𝐞𝐥/𝐠𝐫𝐨𝐮𝐩 𝐞 𝐀𝐝𝐦𝐢𝐧 𝐤𝐨𝐫𝐮𝐧!</b>")    try:        invite_link = await bot.create_chat_invite_link(chat_id)        link_url = invite_link.invite_link    except Exception as e:        if chat.username:            link_url = f"https://t.me/{chat.username}"        else:            return await msg.answer(f"❌ <b>𝐈𝐧𝐯𝐢𝐭𝐞 𝐥𝐢𝐧𝐤 𝐭𝐨𝐢𝐫𝐢 𝐤𝐨𝐫𝐚 𝐣𝐚𝐲 𝐧𝐚𝐢.</b>\n𝐁𝐨𝐭 𝐤𝐞 'Invite Users via Link' 𝐩𝐞𝐫𝐦𝐢𝐬𝐬𝐢𝐨𝐧 𝐝𝐢𝐧.")    await DB.execute(        "INSERT INTO channels(chat_id,title,invite_link,added_at) VALUES(?,?,?,?) "        "ON CONFLICT(chat_id) DO UPDATE SET title=excluded.title, invite_link=excluded.invite_link",        (chat_id, title, link_url, datetime.utcnow().isoformat())    )    await DB.commit()    await state.clear()    await msg.answer(        f"✅ <b>{title}</b> 𝐬𝐞𝐭 𝐡𝐨𝐲𝐞𝐜𝐡𝐞!\n"        f"🆔 <code>{chat_id}</code>\n"        f"🔗 {link_url}",        reply_markup=admin_keyboard()    )@router.callback_query(F.data == "adm_join_list")async def cb_adm_join_list(cb: CallbackQuery):    if not owner_only(cb): return    ch = await get_all_channels()    txt = "📋 <b>𝐉𝐨𝐢𝐧 𝐋𝐢𝐬𝐭</b>\n\n" + (        "\n\n".join(f"• <b>{c['title']}</b>\n🆔 <code>{c['chat_id']}</code>\n🔗 {c['invite_link']}" for c in ch) if ch else "❌ 𝐍𝐨𝐧𝐞."    )    await cb.message.edit_text(txt, reply_markup=InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="⬅️ 𝐁𝐚𝐜𝐤", callback_data="adm_join_set")]]))@router.callback_query(F.data == "adm_join_delete")async def cb_adm_join_delete(cb: CallbackQuery, state: FSMContext):    if not owner_only(cb): return    await state.set_state(AdminStates.del_channel)    await cb.message.edit_text("🗑 <b>𝐃𝐞𝐥𝐞𝐭𝐞 𝐂𝐡𝐚𝐧𝐧𝐞𝐥</b>\n\n𝐒𝐞𝐧𝐝 𝐓𝐢𝐭𝐥𝐞 / 𝐂𝐡𝐚𝐭𝐈𝐃:")@router.message(AdminStates.del_channel)async def adm_del_channel(msg: Message, state: FSMContext):    if msg.from_user.id != OWNER_ID: return    async with DB.execute("SELECT * FROM channels WHERE title=? OR invite_link=? OR chat_id=?", (msg.text.strip(), msg.text.strip(), msg.text.strip())) as cur:        row = await cur.fetchone()    if not row: return await msg.answer("❌ 𝐍𝐨𝐭 𝐬𝐞𝐭.", reply_markup=admin_keyboard())    await DB.execute("DELETE FROM channels WHERE chat_id=?", (row["chat_id"],))    await DB.commit()    await state.clear()    await msg.answer(f"🗑 𝐃𝐞𝐥𝐞𝐭𝐞𝐝.", reply_markup=admin_keyboard())# ---- Redeem ----@router.callback_query(F.data == "adm_redeem")async def cb_adm_redeem(cb: CallbackQuery, state: FSMContext):    if not owner_only(cb): return    await state.set_state(AdminStates.add_redeem)    await cb.message.edit_text("🎁 <b>𝐑𝐞𝐝𝐞𝐞𝐦 𝐂𝐫𝐞𝐚𝐭𝐞</b>\n\n𝐅𝐨𝐫𝐦𝐚𝐭: <code>𝐂𝐎𝐃𝐄 | 𝐓𝐎𝐊𝐄𝐍𝐒</code>")@router.message(AdminStates.add_redeem)async def adm_add_redeem(msg: Message, state: FSMContext):    if msg.from_user.id != OWNER_ID: return    if "|" not in msg.text: return await msg.answer("❌ 𝐖𝐫𝐨𝐧𝐠 𝐟𝐨𝐫𝐦𝐚𝐭.")    code, tok = [x.strip() for x in msg.text.split("|", 1)]    try: tok = int(tok)    except: return await msg.answer("❌ 𝐈𝐧𝐯𝐚𝐥𝐢𝐝 𝐧𝐮𝐦𝐛𝐞𝐫.")    await DB.execute("INSERT OR REPLACE INTO redeem(code,tokens,used_by,created) VALUES(?,?,NULL,?)", (code, tok, datetime.utcnow().isoformat()))    await DB.commit()    await state.clear()    await msg.answer(f"✅ 𝐂𝐫𝐞𝐚𝐭𝐞𝐝: <code>{code}</code> → {tok} 𝐓𝐨𝐤𝐞𝐧𝐬", reply_markup=admin_keyboard())# ---- Broadcast ----@router.callback_query(F.data == "adm_broadcast")async def cb_adm_broadcast(cb: CallbackQuery, state: FSMContext):    if not owner_only(cb): return    await state.set_state(AdminStates.bc_wait_media)    await cb.message.edit_text("📣 <b>𝐁𝐫𝐨𝐚𝐝𝐜𝐚𝐬𝐭</b>\n\n𝐒𝐞𝐧𝐝 𝐩𝐡𝐨𝐭𝐨/𝐯𝐢𝐝𝐞𝐨/𝐚𝐮𝐝𝐢𝐨/𝐭𝐞𝐱𝐭.\n❌ 𝐂𝐚𝐧𝐜𝐞𝐥: /cancel")@router.message(AdminStates.bc_wait_media)async def adm_bc_media(msg: Message, state: FSMContext):    if msg.from_user.id != OWNER_ID: return    if msg.text == "/cancel": await state.clear(); return await msg.answer("❌ 𝐂𝐚𝐧𝐜𝐞𝐥𝐥𝐞𝐝.", reply_markup=admin_keyboard())    mt, fid, cap = None, None, ""    if msg.video: mt, fid, cap = "video", msg.video.file_id, msg.caption or ""    elif msg.photo: mt, fid, cap = "photo", msg.photo[-1].file_id, msg.caption or ""    elif msg.audio: mt, fid, cap = "audio", msg.audio.file_id, msg.caption or ""    elif msg.text: mt, fid, cap = "text", None, msg.text    if not mt: return await msg.answer("❌ 𝐒𝐞𝐧𝐝 𝐦𝐞𝐝𝐢𝐚/𝐭𝐞𝐱𝐭.")    await state.update_data(bc_media_type=mt, bc_file_id=fid, bc_caption=cap)    await state.set_state(AdminStates.bc_wait_token)    await msg.answer("💰 𝐓𝐨𝐤𝐞𝐧𝐬 𝐫𝐞𝐪𝐮𝐢𝐫𝐞𝐝? (0 = 𝐟𝐫𝐞𝐞)")@router.message(AdminStates.bc_wait_token)async def adm_bc_token(msg: Message, state: FSMContext):    if msg.from_user.id != OWNER_ID: return    try: price = int(msg.text.strip())    except: return await msg.answer("❌ 𝐄𝐧𝐭𝐞𝐫 𝐧𝐮𝐦𝐛𝐞𝐫.")    await state.update_data(bc_price=price)    if price > 0:        await state.set_state(AdminStates.bc_wait_link_media)        await msg.answer("🔒 𝐒𝐞𝐧𝐝 𝐩𝐚𝐢𝐝 𝐯𝐢𝐝𝐞𝐨/𝐩𝐡𝐨𝐭𝐨:")    else:        await state.set_state(None)        await _do_broadcast(msg, state, 0, None, None, "")@router.message(AdminStates.bc_wait_link_media)async def adm_bc_locked(msg: Message, state: FSMContext):    if msg.from_user.id != OWNER_ID: return    if msg.video: lt, lf, lc = "video", msg.video.file_id, msg.caption or ""    elif msg.photo: lt, lf, lc = "photo", msg.photo[-1].file_id, msg.caption or ""    else: return await msg.answer("❌ 𝐒𝐞𝐧𝐝 𝐯𝐢𝐝𝐞𝐨/𝐩𝐡𝐨𝐭𝐨.")    data = await state.get_data()    await state.set_state(None)    await _do_broadcast(msg, state, data["bc_price"], lt, lf, lc, media_type=data["bc_media_type"], file_id=data["bc_file_id"], caption=data["bc_caption"])async def _do_broadcast(msg: Message, state: FSMContext, price: int, locked_type, locked_fid, locked_caption, media_type=None, file_id=None, caption=""):    if media_type is None:        d = await state.get_data()        media_type, file_id, caption = d.get("bc_media_type"), d.get("bc_file_id"), d.get("bc_caption", "")    cur = await DB.execute("INSERT INTO broadcast(media_type,file_id,caption,price,locked_type,locked_file_id,locked_caption,created) VALUES(?,?,?,?,?,?,?,?)", (media_type, file_id, caption, price, locked_type, locked_fid, locked_caption, datetime.utcnow().isoformat()))    bc_id = cur.lastrowid    async with DB.execute("SELECT user_id FROM users WHERE is_banned=0") as c: rows = await c.fetchall()    sent, failed = 0, 0    prog = await msg.answer(f"📤 𝐁𝐫𝐨𝐚𝐝𝐜𝐚𝐬𝐭𝐢𝐧𝐠 𝐭𝐨 {len(rows)} 𝐮𝐬𝐞𝐫𝐬...")    for i, r in enumerate(rows, 1):        try:            kb = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text=f"🔓 𝐁𝐮𝐲 ({price} 𝐓𝐨𝐤𝐞𝐧𝐬)", callback_data=f"bcbuy_{bc_id}")]]) if price > 0 else None            if media_type == "video": await bot.send_video(r["user_id"], file_id, caption=caption, reply_markup=kb)            elif media_type == "photo": await bot.send_photo(r["user_id"], file_id, caption=caption, reply_markup=kb)            elif media_type == "audio": await bot.send_audio(r["user_id"], file_id, caption=caption, reply_markup=kb)            else: await bot.send_message(r["user_id"], caption, reply_markup=kb)            sent += 1            await asyncio.sleep(0.08)        except: failed += 1        if i % 50 == 0:            try: await prog.edit_text(f"📤 𝐏𝐫𝐨𝐠𝐫𝐞𝐬𝐬: {i}/{len(rows)}")            except: pass    await DB.execute("UPDATE broadcast SET sent=?, failed=? WHERE id=?", (sent, failed, bc_id))    await DB.commit()    await prog.edit_text(f"✅ 𝐃𝐨𝐧𝐞!\n\n📤 𝐒𝐞𝐧𝐭: {sent}\n❌ 𝐅𝐚𝐢𝐥𝐞𝐝: {failed}\n💰 𝐏𝐫𝐢𝐜𝐞: {price}", reply_markup=admin_keyboard())@router.callback_query(F.data.startswith("bcbuy_"))async def cb_bc_buy(cb: CallbackQuery):    if not await require_join(cb): return    bc_id = int(cb.data.split("_")[1])    async with DB.execute("SELECT * FROM broadcast WHERE id=?", (bc_id,)) as cur: bc = await cur.fetchone()    if not bc: return await cb.answer("❌ 𝐍𝐨𝐭 𝐟𝐨𝐮𝐧𝐝.", show_alert=True)    if not await deduct_token(cb.from_user.id, bc["price"]): return await cb.answer(f"❌ 𝐍𝐞𝐞𝐝 {bc['price']} 𝐭𝐨𝐤𝐞𝐧𝐬!", show_alert=True)    try:        if bc["locked_type"] == "video": sent = await bot.send_video(cb.from_user.id, bc["locked_file_id"], caption=bc["locked_caption"] or "", protect_content=True)        else: sent = await bot.send_photo(cb.from_user.id, bc["locked_file_id"], caption=bc["locked_caption"] or "", protect_content=True)        delete_at = datetime.utcnow() + timedelta(hours=BCL_DELETE_HOURS)        warn = await bot.send_message(cb.from_user.id, "➥ 𝚃𝚑𝚒𝚜 𝙼𝚊𝚜𝚜𝚊𝚐𝚎 𝚆𝚒𝚕𝚕 𝙱𝚎 𝙳𝚎𝚕𝚎𝚝𝚎𝚍 𝙸𝚗 𝟷 𝙳𝚊𝚢.")        await schedule_delete(cb.from_user.id, sent.message_id, delete_at)        await schedule_delete(cb.from_user.id, warn.message_id, delete_at)        await cb.answer("✅ 𝐔𝐧𝐥𝐨𝐜𝐤𝐞𝐝!")    except: await add_token(cb.from_user.id, bc["price"]); await cb.answer("❌ 𝐄𝐫𝐫𝐨𝐫, 𝐫𝐞𝐟𝐮𝐧𝐝𝐞𝐝.", show_alert=True)# ---- BC-Links ----@router.callback_query(F.data == "adm_bc_links")async def cb_adm_bc_links(cb: CallbackQuery, state: FSMContext):    if not owner_only(cb): return    await state.set_state(AdminStates.bcl_wait_caption)    await cb.message.edit_text("🔗 <b>𝐁𝐫𝐨𝐚𝐝𝐜𝐚𝐬𝐭-𝐋𝐢𝐧𝐤𝐬</b>\n\n𝐒𝐭𝐞𝐩 1/3: 𝐒𝐞𝐧𝐝 <b>𝐩𝐡𝐨𝐭𝐨/𝐚𝐮𝐝𝐢𝐨/𝐭𝐞𝐱𝐭</b>:\n❌ 𝐂𝐚𝐧𝐜𝐞𝐥: /cancel")@router.message(AdminStates.bcl_wait_caption)async def bcl_step1(msg: Message, state: FSMContext):    if msg.from_user.id != OWNER_ID: return    if msg.text == "/cancel": await state.clear(); return await msg.answer("❌ 𝐂𝐚𝐧𝐜𝐞𝐥𝐥𝐞𝐝.", reply_markup=admin_keyboard())    mt, fid, cap = None, None, ""    if msg.photo: mt, fid, cap = "photo", msg.photo[-1].file_id, msg.caption or ""    elif msg.audio: mt, fid, cap = "audio", msg.audio.file_id, msg.caption or ""    elif msg.video: mt, fid, cap = "video", msg.video.file_id, msg.caption or ""    elif msg.text: mt, fid, cap = "text", None, msg.text    if not mt: return await msg.answer("❌ 𝐒𝐞𝐧𝐝 𝐦𝐞𝐝𝐢𝐚/𝐭𝐞𝐱𝐭.")    await state.update_data(bcl_mt=mt, bcl_fid=fid, bcl_cap=cap)    await state.set_state(AdminStates.bcl_wait_price)    await msg.answer("𝐒𝐭𝐞𝐩 2/3: 💰 𝐓𝐨𝐤𝐞𝐧𝐬 𝐫𝐞𝐪𝐮𝐢𝐫𝐞𝐝?")@router.message(AdminStates.bcl_wait_price)async def bcl_step2(msg: Message, state: FSMContext):    if msg.from_user.id != OWNER_ID: return    if msg.text == "/cancel": await state.clear(); return await msg.answer("❌ 𝐂𝐚𝐧𝐜𝐞𝐥𝐥𝐞𝐝.", reply_markup=admin_keyboard())    try: price = int(msg.text.strip())    except: return await msg.answer("❌ 𝐄𝐧𝐭𝐞𝐫 𝐧𝐮𝐦𝐛𝐞𝐫.")    await state.update_data(bcl_price=price)    await state.set_state(AdminStates.bcl_wait_locked)    await msg.answer("𝐒𝐭𝐞𝐩 3/3: 📸 𝐒𝐞𝐧𝐝 <b>𝐩𝐚𝐢𝐝 𝐯𝐢𝐝𝐞𝐨/𝐩𝐡𝐨𝐭𝐨</b>:")@router.message(AdminStates.bcl_wait_locked)async def bcl_step3(msg: Message, state: FSMContext):    if msg.from_user.id != OWNER_ID: return    if msg.text == "/cancel": await state.clear(); return await msg.answer("❌ 𝐂𝐚𝐧𝐜𝐞𝐥𝐥𝐞𝐝.", reply_markup=admin_keyboard())    if msg.video: lt, lf, lc = "video", msg.video.file_id, msg.caption or ""    elif msg.photo: lt, lf, lc = "photo", msg.photo[-1].file_id, msg.caption or ""    else: return await msg.answer("❌ 𝐒𝐞𝐧𝐝 𝐯𝐢𝐝𝐞𝐨/𝐩𝐡𝐨𝐭𝐨.")    data = await state.get_data()    await state.set_state(None)    cur = await DB.execute("INSERT INTO broadcast_links(media_type,file_id,caption,price,locked_type,locked_file_id,locked_caption,created) VALUES(?,?,?,?,?,?,?,?)", (data["bcl_mt"], data["bcl_fid"], data["bcl_cap"], data["bcl_price"], lt, lf, lc, datetime.utcnow().isoformat()))    bcl_id = cur.lastrowid    async with DB.execute("SELECT user_id FROM users WHERE is_banned=0") as c: rows = await c.fetchall()    sent, failed = 0, 0    prog = await msg.answer(f"📤 𝐁𝐫𝐨𝐚𝐝𝐜𝐚𝐬𝐭𝐢𝐧𝐠 𝐭𝐨 {len(rows)} 𝐮𝐬𝐞𝐫𝐬...")    kb = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text=f"🔓 𝐔𝐧𝐥𝐨𝐜𝐤 ({data['bcl_price']} 𝐓𝐨𝐤𝐞𝐧𝐬)", callback_data=f"bcl_buy_{bcl_id}")]])    for i, r in enumerate(rows, 1):        try:            if data["bcl_mt"] == "photo": await bot.send_photo(r["user_id"], data["bcl_fid"], caption=data["bcl_cap"], reply_markup=kb)            elif data["bcl_mt"] == "audio": await bot.send_audio(r["user_id"], data["bcl_fid"], caption=data["bcl_cap"], reply_markup=kb)            elif data["bcl_mt"] == "video": await bot.send_video(r["user_id"], data["bcl_fid"], caption=data["bcl_cap"], reply_markup=kb)            else: await bot.send_message(r["user_id"], data["bcl_cap"], reply_markup=kb)            sent += 1            await asyncio.sleep(0.08)        except: failed += 1        if i % 50 == 0:            try: await prog.edit_text(f"📤 𝐏𝐫𝐨𝐠𝐫𝐞𝐬𝐬: {i}/{len(rows)}")            except: pass    await DB.execute("UPDATE broadcast_links SET sent=?, failed=? WHERE id=?", (sent, failed, bcl_id))    await DB.commit()    await prog.edit_text(f"✅ 𝐁𝐫𝐨𝐚𝐝𝐜𝐚𝐬𝐭-𝐋𝐢𝐧𝐤𝐬 𝐃𝐨𝐧𝐞!\n\n📤 𝐒𝐞𝐧𝐭: {sent}\n❌ 𝐅𝐚𝐢𝐥𝐞𝐝: {failed}\n💰 𝐏𝐫𝐢𝐜𝐞: {data['bcl_price']}\n⏰ 𝐀𝐮𝐭𝐨-𝐝𝐞𝐥𝐞𝐭𝐞: 1 𝐃𝐚𝐲", reply_markup=admin_keyboard())@router.callback_query(F.data.startswith("bcl_buy_"))async def cb_bcl_buy(cb: CallbackQuery):    if not await require_join(cb): return    bcl_id = int(cb.data.split("_")[-1])    async with DB.execute("SELECT * FROM broadcast_links WHERE id=?", (bcl_id,)) as cur: row = await cur.fetchone()    if not row: return await cb.answer("❌ 𝐍𝐨𝐭 𝐟𝐨𝐮𝐧𝐝.", show_alert=True)    if not await deduct_token(cb.from_user.id, row["price"]): return await cb.answer(f"❌ 𝐍𝐞𝐞𝐝 {row['price']} 𝐭𝐨𝐤𝐞𝐧𝐬!", show_alert=True)    try:        if row["locked_type"] == "video": sent = await bot.send_video(cb.from_user.id, row["locked_file_id"], caption=row["locked_caption"] or "", protect_content=True)        else: sent = await bot.send_photo(cb.from_user.id, row["locked_file_id"], caption=row["locked_caption"] or "", protect_content=True)        delete_at = datetime.utcnow() + timedelta(hours=BCL_DELETE_HOURS)        warn = await bot.send_message(cb.from_user.id, "➥ 𝚃𝚑𝚒𝚜 𝙼𝚊𝚜𝚜𝚊𝚐𝚎 𝚆𝚒𝚕𝚕 𝙱𝚎 𝙳𝚎𝚕𝚎𝚝𝚎𝚍 𝙸𝚗 𝟷 𝙳𝚊𝚢.")        await schedule_delete(cb.from_user.id, sent.message_id, delete_at)        await schedule_delete(cb.from_user.id, warn.message_id, delete_at)        await cb.answer("✅ 𝐔𝐧𝐥𝐨𝐜𝐤𝐞𝐝! 𝐀𝐮𝐭𝐨-𝐝𝐞𝐥𝐞𝐭𝐞𝐬 𝐢𝐧 1 𝐝𝐚𝐲.")    except: await add_token(cb.from_user.id, row["price"]); await cb.answer("❌ 𝐄𝐫𝐫𝐨𝐫, 𝐫𝐞𝐟𝐮𝐧𝐝𝐞𝐝.", show_alert=True)# ---- Bot ON/OFF ----@router.callback_query(F.data == "adm_bot_toggle")async def cb_adm_bot_toggle(cb: CallbackQuery):    if not owner_only(cb): return    new = not await is_bot_on()    await set_bot_status(new)    await cb.answer(f"𝐁𝐨𝐭 𝐧𝐨𝐰 {'𝐎𝐍 🟢' if new else '𝐎𝐅𝐅 🔴'}", show_alert=True)    await cb.message.edit_text(f"🛠 <b>𝐀𝐃𝐌𝐈𝐍 𝐏𝐀𝐍𝐄𝐋</b>\n\n🔌 𝐒𝐭𝐚𝐭𝐮𝐬: {'🟢 𝐎𝐍' if new else '🔴 𝐎𝐅𝐅'}", reply_markup=admin_keyboard())# ==================== MAIN RUNNER ====================async def main():    await db_init()    asyncio.create_task(delete_worker())    asyncio.create_task(force_join_worker())    log.info("🚀 Bot starting in High-Load Mode...")    try:         await dp.start_polling(bot)    finally:         await db_close()if __name__ == "__main__":    try:         asyncio.run(main())    except (KeyboardInterrupt, SystemExit):         log.info("Stopped.")